const type = $input.first().json.body.type;
const templates = {
  new_signup: `New signup: {{name}} ({{tier}})`,
  payment_failure: `Payment failed: {{client_id}}`,
  workflow_failure: `Workflow failed: {{workflow_id}} - {{reason}}`,
  health_stale: `Stale workflow: {{client_id}} ({{tier}})`,
  circuit_breaker: `Circuit broken: {{client_id}}`,
  usage_limit: `Usage limit: {{client_id}} at {{percent}}%`,
  subscription_change: `Status: {{old}} -> {{new}}`,
  oauth_refresh_failed: `OAuth refresh failed for {{client_id}} ({{provider}})`
};
const body = $input.first().json.body;
let text = templates[type] || 'Unknown alert';
Object.keys(body).forEach(key => {
  text = text.replace(new RegExp(`{{${key}}}`, 'g'), body[key]);
});
return [{ json: { text } }];
